import{_ as r,c as t,o,aj as a}from"./chunks/framework.Id7s26SP.js";const u=JSON.parse('{"title":"Interface: DocumentWriteRefusedEvent","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentWriteRefusedEvent.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentWriteRefusedEvent.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/DocumentWriteRefusedEvent.md"};function c(d,e,s,i,l,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentWriteRefusedEvent</p><h1 id="interface-documentwriterefusedevent" tabindex="-1">Interface: DocumentWriteRefusedEvent <a class="header-anchor" href="#interface-documentwriterefusedevent" aria-label="Permalink to “Interface: DocumentWriteRefusedEvent”">​</a></h1><p>Payload of the <code>document:write-refused</code> event (<code>client.on(&quot;document:write-refused&quot;, ...)</code>).</p><p>Fired for EVERY local write a large document refuses because it is past its offline write window — the same event, by the same name, the Swift client emits. A call that can throw throws <a href="#error">error</a> as well, so the throw stays the call site&#39;s signal; this is the channel for handling the refusal once, in one place, on either client.</p><p>Nothing is emitted for an accepted write, for an ordinary (format-1) document, or for a refusal of another kind.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h3><blockquote><p><strong>documentId</strong>: <code>string</code></p></blockquote><hr><h3 id="error" tabindex="-1">error <a class="header-anchor" href="#error" aria-label="Permalink to “error”">​</a></h3><blockquote><p><strong>error</strong>: <code>DocumentOfflineWindowError</code></p></blockquote><p>The very error the call threw: <code>code</code> is <code>DOCUMENT_OFFLINE_WINDOW_EXPIRED</code>, and <code>details</code> carries <code>documentId</code>, <code>lastSyncAt</code>, <code>windowDays</code> and <code>overdueMs</code>.</p><hr><h3 id="model" tabindex="-1">model <a class="header-anchor" href="#model" aria-label="Permalink to “model”">​</a></h3><blockquote><p><strong>model</strong>: <code>string</code></p></blockquote><p>The model the refused write was on.</p><hr><h3 id="recordid" tabindex="-1">recordId <a class="header-anchor" href="#recordid" aria-label="Permalink to “recordId”">​</a></h3><blockquote><p><strong>recordId</strong>: <code>string</code></p></blockquote><p>The record it was on.</p>',22)])])}const m=r(n,[["render",c]]);export{u as __pageData,m as default};
